def add_lists(list1, list2):

    # check if inputs are lists
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise ValueError("Both inputs should be of list type")

    # check if elements of lists are integers
    if not all(isinstance(i, int) for i in list1) or not all(isinstance(i, int) for i in list2):
        raise ValueError("List elements should be integers")

    # find the length of larger list for iteration
    n = max(len(list1), len(list2))

    # extend shorter list with zeros 
    if len(list1) < n:
        list1 += [0] * (n - len(list1))
    if len(list2) < n:
        list2 += [0] * (n - len(list2))

    # use zip to iterate over both lists at the same time, summing each pair
    return [a + b for a, b in zip(list1, list2)]

def count_distinct_vowels(string):
    vowels = ['a', 'e', 'i', 'o', 'u']
    distinct_vowels = set()
    prev_vowel = None

    for char in string.lower():
        if char in vowels:
            if char != prev_vowel:
                distinct_vowels.add(char)
            prev_vowel = char

    return len(distinct_vowels)

def multiply_without_operator(num_1: int, num_2: int) -> int:
    if num_1 == 0 or num_2 == 0:
        return 0

    negative_result = False
    if num_1 < 0:
        num_1 = -num_1
        negative_result = not negative_result
    if num_2 < 0:
        num_2 = -num_2
        negative_result = not negative_result

    result = 0
    for _ in range(num_2):
        result += num_1

    return -result if negative_result else result

import math

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def print_primes(n):
    if type(n) != int or n < 1:
        print("Invalid input")
        return
    for i in range(2, n+1):
        if is_prime(i):
            print(i, end=" ")
    print()

