class StringManipulator:
    def __init__(self, string):
        self.string = string

    def capitalize_first_letter(self):
        self.string = self.string.capitalize()

    def reverse_capitalization(self):
        reversed_string = ''
        for char in self.string:
            if char.isalpha():
                if char.isupper():
                    reversed_string += char.lower()
                else:
                    reversed_string += char.upper()
            else:
                reversed_string += char
        self.string = reversed_string

    def count_character(self, char):
        return self.string.count(char)

