def compute_tree_height(node): 
    if node is None: 
        return -1;   
    else :
        # Compute the depth of each subtree and use recursion
        left_depth = compute_tree_height(node.left) 
        right_depth = compute_tree_height(node.right) 

        # Use the larger one 
        if (left_depth > right_depth): 
            return left_depth+1
        else: 
            return right_depth+1

